const ICONS={home:'M3 10 12 3l9 7M5 9v12h5v-7h4v7h5V9',map:'m3 5 6-2 6 2 6-2v16l-6 2-6-2-6 2V5zm6-2v16m6-14v16',book:'M12 5C8 2 3 3 3 3v16s5-1 9 2c4-3 9-2 9-2V3s-5-1-9 2v16',scan:'M8 3H3v5m13-5h5v5M3 16v5h5m8 0h5v-5M7 12h10M9 8h6v8H9z',stamp:'M6 14h12l2 5H4l2-5zm4 0V9a4 4 0 1 1 4 0v5M5 22h14',pin:'M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0zm-8-3a3 3 0 1 0 0 6 3 3 0 0 0 0-6',clock:'M12 8v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',star:'m12 3 2.8 5.7 6.2.9-4.5 4.4 1.1 6.2-5.6-3-5.6 3 1.1-6.2L3 9.6l6.2-.9L12 3z',chevron:'m9 5 7 7-7 7',back:'m15 5-7 7 7 7',check:'m5 12 4 4L19 6',close:'m6 6 12 12M6 18 18 6',sound:'M11 4 6 8H3v8h3l5 4V4zm4 4c3 2 3 6 0 8m3-11c5 4 5 10 0 14',user:'M20 21v-2a7 7 0 0 0-14 0v2M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',settings:'M4 7h16M4 17h16M8 4v6m8 4v6',leaf:'M20 3C5 2 2 11 7 17c5 5 14-1 13-14zM4 21 16 8',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',camera:'M3 7h4l2-3h6l2 3h4v14H3V7zm13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',layers:'m12 3 10 6-10 6L2 9l10-6zM2 14l10 6 10-6',info:'M12 11v6m0-10v1M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',edit:'m4 15 11-11 5 5L9 20H4v-5zm9-9 5 5',lock:'M6 10V7a6 6 0 0 1 12 0v3M4 10h16v12H4z',play:'m8 4 13 8-13 8V4',grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',vr:'M3 8h18v9h-6l-3-3-3 3H3V8zm5 4.5h.01M16 12.5h.01',cube:'m12 3 8 4.5v9L12 21l-8-4.5v-9L12 3zm0 9 8-4.5M12 12 4 7.5M12 12v9',move:'M12 5v14m-5-5 5 5 5-5'};
const icon=n=>`<svg class="icon" aria-hidden="true" viewBox="0 0 24 24"><path d="${ICONS[n]||ICONS.leaf}"/></svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const asset=n=>(window.CUCHI_ASSETS||{})[n]||`assets/${n}`;
const DEFAULT_STORIES=[
{id:'nap-ham',code:'CC-01',title:'Bên dưới những chiếc lá',category:'Khám phá',image:'023.webp',minutes:4,stamp:'MẮT TINH',excerpt:'Một lối vào nhỏ. Một thế giới khác dưới chân. Bắt đầu bằng việc nhìn chậm lại.',lead:'Nếu không dừng lại, bạn có nhận ra một lối đi ngay dưới những chiếc lá?',body:'Hãy quan sát bức ảnh lối vào địa đạo. Mép cửa, nền đất và lớp lá nằm gần nhau đến mức rất dễ lướt qua. Đừng vội tìm câu trả lời: thử nhìn vào hình dáng, đường viền và những thay đổi nhỏ trên bề mặt.\n\nỞ trạm này, câu chuyện bắt đầu từ một vật rất nhỏ: chiếc nắp hầm. Một lối vào không chỉ là nơi bước xuống. Nó còn gợi câu hỏi về cách con người thích nghi với cảnh quan và sử dụng những vật liệu quanh mình.\n\nChuyển sang lớp khám phá để xem các điểm được chú thích trên ảnh. Sau đó, trở lại và thử nhận ra chi tiết quan trọng nhất. Khi tham quan thực tế, chỉ tiếp cận lối xuống được hướng dẫn viên cho phép.',question:'Trong bức ảnh, chi tiết nào giúp lối vào hòa vào nền đất?',options:['Lớp lá và màu đất quanh miệng hầm','Một tấm biển lớn đặt trên cửa','Ánh sáng từ dưới hầm'],answer:0,explanation:'Lớp lá và màu đất khiến đường viền lối vào khó nhận ra hơn. Bạn vừa hoàn thành một lượt quan sát có chủ đích.'},
{id:'lo-thong-hoi',code:'CC-02',title:'Một hơi thở của đất',category:'Khám phá',image:'057.webp',minutes:3,stamp:'TINH Ý',excerpt:'Dừng lại trước một chi tiết nhỏ trên mặt đất để nghĩ về không gian phía dưới.',lead:'Điều gì kết nối một không gian dưới đất với thế giới phía trên?',body:'Bức ảnh trong bộ tư liệu được ghi tên là lỗ thông hơi của địa đạo Củ Chi. Hãy quan sát hình dáng, bề mặt và vị trí của nó trước khi mở chú thích.\n\nThay vì chỉ nhìn địa đạo như một đường đi, hãy thử nghĩ về các nhu cầu của con người bên trong: không khí, ánh sáng và sự kết nối. Mỗi nhu cầu mở ra một cách đọc không gian khác nhau.\n\nSơ đồ khám phá trong ứng dụng giúp bạn hình dung mối liên hệ giữa mặt đất và không gian phía dưới. Đây là sơ đồ minh họa, không phải bản đo địa đạo tại một vị trí cụ thể.',question:'Lỗ thông hơi gợi đến nhu cầu nào của không gian dưới đất?',options:['Trang trí lối tham quan','Trao đổi không khí','Đánh dấu nơi chụp ảnh'],answer:1,explanation:'Điểm quan sát này dẫn chúng ta đến nhu cầu trao đổi không khí của không gian dưới đất.'},
{id:'bep-hoang-cam',code:'CC-03',title:'Giữ ấm một bữa cơm',category:'Đời sống',image:'066.webp',minutes:4,stamp:'ĐỒNG CẢM',excerpt:'Từ gian bếp, nhìn lịch sử qua những nhu cầu gần gũi nhất của đời sống.',lead:'Có những câu chuyện bắt đầu từ một bữa cơm, không phải từ một trận đánh.',body:'Trong ảnh tư liệu là khu bếp Hoàng Cầm. Hãy nhìn những đồ vật quanh bếp: chúng gợi ra công việc, việc chuẩn bị và nhịp sinh hoạt hằng ngày.\n\nMột điểm tham quan có thể được nhìn từ nhiều phía. Khi chú ý đến bếp, ta dành chỗ cho câu hỏi về ăn uống, chăm sóc và duy trì đời sống. Những vật dụng bình thường cũng có thể mở ra một câu chuyện đáng lắng nghe.\n\nKhi gặp hướng dẫn viên, bạn có thể hỏi: “Chi tiết nào ở khu bếp thường bị khách tham quan bỏ qua?” Câu trả lời cụ thể tại điểm đến sẽ bổ sung cho những gì bức ảnh chưa thể kể.',question:'Góc nhìn nào được câu chuyện này đặt ở trung tâm?',options:['Kỷ lục về chiều dài địa đạo','Kỹ thuật chụp ảnh phong cảnh','Bữa ăn và sinh hoạt hằng ngày'],answer:2,explanation:'Góc nhìn đời sống giúp chúng ta chú ý đến những nhu cầu và công việc bình thường của con người.'},
{id:'long-dia-dao',code:'CC-04',title:'Theo một đường đất nhỏ',category:'Không gian',image:'038.webp',minutes:4,stamp:'KHÁM PHÁ',excerpt:'Nhìn vào lòng địa đạo và thử cảm nhận sự thay đổi của không gian.',lead:'Khi không gian thu hẹp, cách quan sát của chúng ta cũng thay đổi.',body:'Nhìn bức ảnh lòng địa đạo: đường cong, bề mặt đất và khoảng sáng phía trước tạo ra cảm nhận rất khác so với lối đi trên mặt đất.\n\nHãy thử mô tả ba điều bạn thực sự nhìn thấy, trước khi nói về điều bạn tưởng tượng. Việc phân biệt quan sát với suy diễn giúp trải nghiệm lịch sử cẩn trọng và sâu hơn.\n\nSơ đồ trong ứng dụng chỉ phục vụ tìm hiểu. Khi đến di tích, hãy làm theo hướng dẫn về tuyến được mở, sức khỏe và an toàn; không dùng sơ đồ này để tự đi trong địa đạo.',question:'Cách nào giúp quan sát cẩn trọng hơn?',options:['Mô tả điều nhìn thấy trước khi diễn giải','Coi mọi tưởng tượng là sự kiện','Bỏ qua hướng dẫn tại di tích'],answer:0,explanation:'Mô tả trước, diễn giải sau giúp phân biệt bằng chứng trong ảnh với suy nghĩ của riêng mình.'},
{id:'dau-tich',code:'CC-05',title:'Điều mặt đất còn giữ',category:'Ký ức',image:'085.webp',minutes:3,stamp:'LẮNG NGHE',excerpt:'Một khoảng trũng trong rừng, một dấu tích để dừng lại và đặt câu hỏi.',lead:'Một cảnh quan có thể giữ nhiều lớp ký ức hơn những gì ta thấy trong lần nhìn đầu.',body:'Bức ảnh ghi lại một hố bom được giới thiệu tại khu di tích Củ Chi. Hãy quan sát tỷ lệ của khoảng trũng so với cây cối và lối đi quanh nó.\n\nMột dấu tích không tự nói hết câu chuyện của mình. Biển giới thiệu, tư liệu và lời giải thích tại di tích giúp đặt điều ta thấy vào bối cảnh.\n\nỞ trạm này, hãy giữ lại một câu hỏi bạn muốn tìm hiểu thêm. Không cần biến mọi điểm dừng thành một câu trả lời hoàn chỉnh.',question:'Điều gì giúp hiểu dấu tích trong bối cảnh?',options:['Chỉ dựa vào cảm giác khi nhìn ảnh','Đối chiếu biển giới thiệu và tư liệu tại di tích','Đoán sự kiện từ màu của đất'],answer:1,explanation:'Đối chiếu tư liệu và thông tin tại di tích giúp cách hiểu có căn cứ hơn.'},
{id:'loi-rung',code:'CC-06',title:'Mang một câu chuyện về',category:'Ký ức',image:'097.webp',minutes:3,stamp:'GÌN GIỮ',excerpt:'Khép hành trình bằng một điều bạn muốn nhớ, thay vì chỉ một tấm ảnh.',lead:'Bạn sẽ mang điều gì của chuyến đi này về cùng mình?',body:'Hành trình trở lại với lối đi dưới tán cây. Sau những điểm dừng, cùng một cảnh quan có thể gợi cho bạn những câu hỏi khác lúc ban đầu.\n\nHãy chọn một chi tiết mà bạn muốn kể lại: chiếc nắp hầm, lỗ thông hơi, gian bếp hay đường đất. Điều gì khiến nó ở lại trong trí nhớ?\n\nViết một ghi chú ngắn trong hộ chiếu của bạn. Không có câu trả lời mẫu cho ký ức cá nhân. Nếu chia sẻ, hãy phân biệt điều đã quan sát, điều đã được giải thích và cảm nhận riêng của mình.',question:'Khi kể lại chuyến đi, cách nào giúp câu chuyện rõ ràng hơn?',options:['Thêm chi tiết lịch sử chưa kiểm chứng','Chỉ kể số điểm đã nhận','Phân biệt quan sát, thông tin và cảm nhận'],answer:2,explanation:'Ký ức cá nhân có giá trị riêng. Phân biệt nó với thông tin lịch sử giúp người nghe hiểu đúng.'}
];
const JOURNEYS=[{title:'Chạm vào ký ức',desc:'Ba điểm dừng đầu tiên, vừa đủ để bắt đầu nhìn Củ Chi bằng một góc khác.',ids:['nap-ham','lo-thong-hoi','bep-hoang-cam'],time:'11 phút đọc',label:'Hành trình gợi ý'},{title:'Theo dấu lòng đất',desc:'Đi sâu vào cách quan sát không gian, cấu trúc và những chi tiết nhỏ.',ids:['nap-ham','lo-thong-hoi','long-dia-dao','dau-tich'],time:'14 phút đọc',label:'Dành cho người tò mò'},{title:'Một miền ký ức',desc:'Đi qua đủ sáu chương, lưu dấu trải nghiệm và viết điều bạn muốn mang về.',ids:DEFAULT_STORIES.map(x=>x.id),time:'21 phút đọc',label:'Trọn bộ câu chuyện'}];
const STORE='cuchi-stories-v3';
function readStore(key,fallback){try{return JSON.parse(localStorage.getItem(key))||fallback}catch{return fallback}}
let state={journey:0,started:false,completed:[],notes:'',...readStore(STORE,{})};
state.completed=Array.isArray(state.completed)?[...new Set(state.completed)].filter(id=>DEFAULT_STORIES.some(s=>s.id===id)):[];state.journey=Number.isInteger(state.journey)&&JOURNEYS[state.journey]?state.journey:0;
let stories=readStore(STORE+'-content',DEFAULT_STORIES);if(!Array.isArray(stories)||stories.length!==6)stories=structuredClone(DEFAULT_STORIES);
let serverMode=false,csrf='',route='',filter='Tất cả',selectedMap='nap-ham',quizChoice=null,quizFeedback='',stream=null,scanTimer=null,cameraGeneration=0,adminTab='overview',hotspot=0,audioActive=false;
let view3d=null,map3dSelected=null,vrGyro=false,vrStereo=false;const mapLayers={surface:true,l1:true,l2:true,l3:true,route:true};
const app=document.querySelector('#app');const modal=document.querySelector('#modal');
function persist(){try{localStorage.setItem(STORE,JSON.stringify(state))}catch{toast('Trình duyệt không cho lưu. Tiến trình sẽ chỉ giữ trong phiên này.')}}
function toast(msg){const el=document.querySelector('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>el.classList.remove('show'),3600)}
const currentJourney=()=>JOURNEYS[state.journey];
const currentStory=()=>stories.find(s=>currentJourney().ids.includes(s.id)&&!state.completed.includes(s.id))||stories.find(s=>s.id===currentJourney().ids[0]);
const score=()=>state.completed.length*50;
function go(path){if(location.hash==='#/'+path){render()}else location.hash='/'+path}
function header(){const nav=[['','home','Trang chủ'],['journey','map','Hành trình'],['stories','book','Câu chuyện'],['passport','stamp','Hộ chiếu']];return `<header class="topbar"><a class="brand" href="#/" aria-label="Củ Chi Stories — Trang chủ"><span class="brand-symbol">CC</span><span class="brand-name">CỦ CHI<small>STORIES</small></span></a><nav class="desktop-nav" aria-label="Điều hướng chính">${nav.map(([p,i,t])=>`<a href="#/${p}" class="${route===p?'active':''}">${icon(i)}${t}</a>`).join('')}</nav><div class="top-actions"><a class="score" href="#/passport">${icon('star')} ${score()} điểm</a><a class="avatar" href="#/admin" aria-label="Quản lý nội dung">${icon('settings')}</a></div></header>`}
function bottomNav(){return `<nav class="bottom-nav" aria-label="Điều hướng điện thoại">${[['','home','Khám phá'],['map','map','Bản đồ'],['scan','scan','Quét mã'],['stories','book','Chuyện kể'],['passport','stamp','Hộ chiếu']].map(([p,i,t])=>`<a href="#/${p}" class="${route===p?'active ':''}${p==='scan'?'scan-nav':''}" ${route===p?'aria-current="page"':''}>${p==='scan'?`<span class="scan-icon">${icon(i)}</span>`:icon(i)}<span>${t}</span></a>`).join('')}</nav>`}
function footer(){return `<footer class="footer"><span>CỦ CHI STORIES · Đi qua một miền ký ức</span><div><button class="text-btn" data-action="about">Về trải nghiệm</button><button class="text-btn" data-action="credits">Nguồn ảnh</button><a href="#/admin">Quản lý</a></div></footer>`}
function pageHead(kicker,title,desc){return `<div class="page-head"><div class="eyebrow">${kicker}</div><h1>${title}</h1>${desc?`<p>${desc}</p>`:''}</div>`}
function storyCard(s){const done=state.completed.includes(s.id);return `<a class="story-card" href="#/story/${s.id}"><div class="card-image"><img src="${asset(s.image)}" alt="${esc(s.title)}" loading="lazy"><span class="tag">${done?'✓ Đã lưu dấu':esc(s.category)}</span><span class="card-num">${s.code.slice(-2)}</span></div><div class="card-body"><h3>${esc(s.title)}</h3><p>${esc(s.excerpt)}</p><div class="card-bottom"><span class="row">${icon('clock')}${s.minutes} phút đọc</span><span class="row">${done?'Đọc lại':'+50 điểm'} ${icon(done?'check':'chevron')}</span></div></div></a>`}
function home(){const next=currentStory(),count=currentJourney().ids.filter(id=>state.completed.includes(id)).length;return `<div class="intro-line"><span class="eyebrow">Xin chào, người khám phá</span><span class="place">${icon('pin')} Củ Chi, Việt Nam</span></div><section class="hero"><div class="hero-content"><img class="hero-logo" src="${asset('logo.webp')}" alt="Logo nghệ thuật Củ Chi Stories"><h1>Đi qua một<br><em>miền ký ức.</em></h1><p>Đi chậm dưới tán rừng. Lắng nghe chuyện trong lòng đất. Giữ lại một dấu ấn của riêng bạn.</p><div class="actions"><a class="btn cream" href="#/${state.started?'story/'+next.id:'journey'}">${icon(state.started?'play':'map')}${state.started?'Tiếp tục hành trình':'Chọn hành trình'}</a><a class="btn ghost" href="#/scan">${icon('scan')} Quét tại điểm đến</a></div><div class="hero-bottom"><span>${icon('book')} 6 chương chuyện</span><span>${icon('stamp')} 6 dấu ký ức</span><span>${icon('leaf')} Theo nhịp của bạn</span></div></div><div class="hero-image"><img src="${asset('056.webp')}" alt="Ánh sáng xuyên qua tán rừng tại Củ Chi"><div class="vertical-note">NHÌN CHẬM · NGHE SÂU · NHỚ LÂU</div><div class="hero-caption"><div><strong>Dưới tán rừng xanh</strong>Mỗi điểm dừng, một câu chuyện.</div><div class="seal"><div>Ký ức<b>Củ Chi</b>Giữ lại để kể</div></div></div></div></section><a href="#/journey" class="journey-strip"><div><strong>${state.started?'Hành trình của bạn':'Bắt đầu từ ba điều nhỏ'}</strong><p>${state.started?esc(currentJourney().title)+' · '+count+'/'+currentJourney().ids.length+' trạm hoàn thành':'Chiếc nắp hầm · Một hơi thở · Một bữa cơm'}</p></div><div class="steps-mini">${currentJourney().ids.map((id,i)=>`${i?'<i></i>':''}<span class="${state.completed.includes(id)?'done':''}">${state.completed.includes(id)?'✓':String(i+1).padStart(2,'0')}</span>`).join('')}</div></a><div class="section-heading"><div><h2>Chuyện từ lòng đất</h2><p>Chạm vào một câu chuyện để bắt đầu.</p></div><a class="text-btn" href="#/stories">Xem tất cả</a></div><div class="cards home-cards">${stories.slice(0,3).map(storyCard).join('')}</div><div class="feature-row"><div class="feature"><div class="seal"><div>Hộ chiếu<b>Ký ức</b>Củ Chi Stories</div></div><div><h3>Mỗi trạm, một dấu nhớ.</h3><p>Hoàn thành thử thách, sưu tập dấu và viết điều bạn muốn mang về.</p><a href="#/passport" class="text-btn">Mở hộ chiếu ${icon('stamp')}</a></div></div><div class="feature dark"><div><div class="eyebrow">Một góc nhìn khác</div><h3 style="margin-top:13px">Phía sau lớp đất</h3><p>Khám phá từng chi tiết qua các lớp chú thích tương tác.</p><div class="row" style="flex-wrap:wrap;gap:10px"><a href="#/ar/nap-ham" class="btn ghost small">${icon('layers')} Khám phá lớp AR</a><a href="#/explorer" class="btn ghost small">${icon('cube')} Bản đồ 3D</a><a href="#/vr/bep-hoang-cam" class="btn ghost small">${icon('vr')} Vào VR</a></div></div></div></div>`}
function journeys(){let j=currentJourney();return `${pageHead('Tự chọn nhịp đi','Bạn muốn bắt đầu thế nào?','Chọn một mạch chuyện. Bạn vẫn có thể ghé bất kỳ trạm nào trong thư viện.')}<div class="journey-options">${JOURNEYS.map((j,i)=>`<button class="journey-option ${state.journey===i?'selected':''}" data-action="journey" data-index="${i}" aria-pressed="${state.journey===i}"><span class="num">0${i+1}</span>${state.journey===i?`<span class="check">${icon('check')}</span>`:''}<span class="tag">${j.label}</span><h3>${j.title}</h3><p>${j.desc}</p><span class="small">${j.ids.length} trạm · ${j.time}</span></button>`).join('')}</div><div class="itinerary"><section><h2 style="font-size:30px">Những điểm dừng của bạn</h2>${j.ids.map((id,i)=>{const s=stories.find(s=>s.id===id);return `<a href="#/story/${id}" class="station"><span class="station-no">0${i+1}</span><img src="${asset(s.image)}" alt=""><div class="station-text"><h3>${esc(s.title)}</h3><p>${s.minutes} phút đọc · ${state.completed.includes(id)?'Đã đóng dấu':'Một thử thách quan sát'}</p></div><span class="icon-btn">${icon(state.completed.includes(id)?'check':'chevron')}</span></a>`}).join('')}</section><aside class="note"><div class="eyebrow">Sẵn sàng lên đường</div><h3 style="margin-top:16px">${j.title}</h3><p>Đọc chuyện, khám phá chi tiết, rồi hoàn thành một thử thách ngắn tại mỗi trạm.</p><div class="progress-track"><span style="width:${j.ids.filter(id=>state.completed.includes(id)).length/j.ids.length*100}%"></span></div><span class="small">${j.ids.filter(id=>state.completed.includes(id)).length}/${j.ids.length} dấu đã nhận</span><button class="btn" data-action="start">${icon('play')} ${state.started?'Tiếp tục hành trình':'Bắt đầu hành trình'}</button><a href="#/map" class="btn outline">${icon('map')} Xem sơ đồ các trạm</a><p class="small muted">Thời gian trên là thời gian đọc ước tính, chưa gồm di chuyển tại di tích.</p></aside></div>`}
function library(){const shown=stories.filter(s=>filter==='Tất cả'||(filter==='Đã lưu dấu'?state.completed.includes(s.id):s.category===filter));return `${pageHead('Thư viện chuyện kể','Sáu điểm dừng. Nhiều góc nhìn.','Từ những chi tiết nhỏ, tìm một cách gần gũi hơn để hiểu nơi mình đang đến.')}<div class="filters">${['Tất cả','Khám phá','Đời sống','Không gian','Ký ức','Đã lưu dấu'].map(f=>`<button class="chip ${filter===f?'active':''}" data-action="filter" data-value="${f}" aria-pressed="${filter===f}">${f}</button>`).join('')}</div>${shown.length?`<div class="cards">${shown.map(storyCard).join('')}</div>`:'<div class="empty"><h3>Những dấu đầu tiên đang chờ bạn</h3><p>Đọc một câu chuyện và hoàn thành thử thách để lưu dấu.</p><button class="btn" data-action="filter" data-value="Tất cả" style="margin-top:20px">Khám phá câu chuyện</button></div>'}`}
function storyPage(id){const s=stories.find(x=>x.id===id);if(!s)return notFound();const done=state.completed.includes(id);return `<a class="back" href="#/stories">${icon('back')} Thư viện chuyện kể</a><div class="story-layout"><article class="article"><img class="article-image" src="${asset(s.image)}" alt="${esc(s.title)}"><div class="story-meta"><span>${s.code} · ${esc(s.category)}</span><span>${s.minutes} phút đọc</span><button class="text-btn" data-action="audio" data-id="${id}" style="font-size:12px">${icon('sound')} <span id="audio-label">Nghe câu chuyện</span></button></div><h1>${esc(s.title)}</h1><p class="lead">${esc(s.lead)}</p><div class="prose">${s.body.split('\n\n').map(p=>`<p>${esc(p)}</p>`).join('')}</div><div class="callout">Câu chuyện diễn giải dùng cho bản trải nghiệm; chưa thay thế nội dung thuyết minh chính thức tại di tích.</div><div class="section-heading"><h3>Thêm một góc nhìn</h3></div><div class="row" style="flex-wrap:wrap"><a class="btn outline" href="#/ar/${id}">${icon('layers')} Lớp khám phá AR</a><a class="btn outline" href="#/vr/${id}">${icon('vr')} Vào cảnh VR</a><a class="btn outline" href="#/explorer">${icon('cube')} Bản đồ 3D địa đạo</a></div></article><aside class="article-aside"><section class="quest" id="quest"><div class="eyebrow">${done?'Dấu đã được lưu':'Thử thách nhỏ · +50 điểm'}</div><h3>${esc(s.question)}</h3>${s.options.map((o,i)=>`<button class="quest-option ${quizChoice===i?'chosen':''} ${quizFeedback&&quizChoice===i?(i===s.answer?'correct':'wrong'):''}" data-action="answer" data-index="${i}" aria-pressed="${quizChoice===i}">${String.fromCharCode(65+i)}. ${esc(o)}</button>`).join('')}${quizFeedback?`<div class="feedback" role="status">${esc(quizFeedback)}</div>`:''}<button class="btn cream" data-action="submit" data-id="${id}" ${quizChoice===null?'disabled':''}>${done?'Kiểm tra câu trả lời':'Kiểm tra & nhận dấu'}</button><p>${done?'Bạn đã nhận 50 điểm tại trạm này. Đọc lại bất cứ khi nào bạn muốn.':'Không cần trả lời vội. Bạn có thể đọc lại hoặc thử thêm lần nữa.'}</p></section><div class="aside-extra"><h3>Hộ chiếu của bạn</h3><div class="progress-track"><span style="width:${state.completed.length/6*100}%"></span></div><p>${state.completed.length}/6 dấu ký ức · ${score()} điểm</p><a href="#/passport" class="text-btn">Xem bộ sưu tập ${icon('stamp')}</a></div></aside></div>`}
function mapPage(){const s=stories.find(s=>s.id===selectedMap)||stories[0],pos=[[30,23],[63,36],[34,53],[72,64],[34,80],[72,88]];return `${pageHead('Theo mạch câu chuyện','Một bản đồ để tò mò.','Chọn một điểm dừng để mở câu chuyện và thử thách.')}<div class="map-layout"><div class="map-board"><span class="map-label">SƠ ĐỒ HÀNH TRÌNH</span><span class="compass">N</span><svg class="map-lines" viewBox="0 0 600 535" preserveAspectRatio="none" aria-hidden="true"><path d="M180 123C200 90 480 120 378 193S40 215 204 284 560 245 432 342 60 340 204 428 480 405 432 470" fill="none" stroke="#89966d" stroke-width="50" opacity=".16"/><path d="M180 123C200 90 480 120 378 193S40 215 204 284 560 245 432 342 60 340 204 428 480 405 432 470" fill="none" stroke="#647448" stroke-width="2" stroke-dasharray="6 7"/></svg>${stories.map((s,i)=>`<button class="pin ${s.id===selectedMap?'selected':''}" style="left:${pos[i][0]}%;top:${pos[i][1]}%" data-action="map-pin" data-id="${s.id}"><img src="${asset(s.image)}" alt="">${s.code}${state.completed.includes(s.id)?' ✓':''}</button>`).join('')}<span class="map-foot">Sơ đồ minh họa · Không dùng để chỉ đường tại di tích.</span></div><div>${storyCard(s)}<div class="note" style="margin-top:20px"><h3>Đang ở điểm tham quan?</h3><p>Quét mã của bản trải nghiệm hoặc nhập mã trạm để mở đúng câu chuyện.</p><a href="#/scan" class="btn">${icon('scan')} Quét / nhập mã trạm</a></div><div class="note" style="margin-top:20px"><h3>Nhìn xuống lòng đất</h3><p>Xem các trạm nằm ở tầng nào của địa đạo trên bản đồ 3D tương tác, hoặc đặt bản đồ lên mã trạm bằng camera.</p><a href="#/explorer" class="btn">${icon('cube')} Mở bản đồ 3D địa đạo</a></div></div></div>`}
function passportPage(){const all=state.completed.length===6;return `${pageHead('Những điều mang theo','Hộ chiếu ký ức','Mỗi dấu là một lần bạn đã dừng lại, quan sát và hiểu thêm.')}<div class="passport"><div class="passport-cover"><span class="eyebrow">Củ Chi Stories</span><h2>Hộ chiếu<br>ký ức</h2><div class="seal"><div>Người<b>${all?'Gìn giữ':'Khám phá'}</b>miền ký ức</div></div><p>Đi để hiểu. Nhớ để kể.</p><small>${state.completed.length}/6 dấu · ${score()} điểm khám phá</small></div><section><div class="row between"><h2 style="font-size:30px">Dấu trên hành trình</h2><span class="tag green">${all?'Trọn bộ ký ức':state.completed.length>=3?'Người lắng nghe':'Người mới đến'}</span></div><div class="stamp-grid">${stories.map((s,i)=>`<a href="#/story/${s.id}" class="stamp-cell ${state.completed.includes(s.id)?'earned':''}" aria-label="${esc(s.title)}: ${state.completed.includes(s.id)?'đã nhận dấu':'chưa nhận dấu'}"><div class="stamp"><span>CỦ CHI</span><b>${state.completed.includes(s.id)?'✦':'0'+(i+1)}</b><span>${esc(s.stamp)}</span></div></a>`).join('')}</div><div class="passport-stats"><div><strong>${score()}</strong><span>điểm đã nhận</span></div><div><strong>${state.completed.length}/6</strong><span>chương hoàn thành</span></div><div><strong>${Math.max(0,6-state.completed.length)}</strong><span>dấu còn chờ</span></div></div><label class="field" for="memory-note">Một điều tôi muốn nhớ<textarea id="memory-note" placeholder="Một chi tiết, một câu hỏi, hay một điều bạn muốn kể lại…" maxlength="2500">${esc(state.notes)}</textarea></label><div class="row" style="flex-wrap:wrap"><button class="btn" data-action="save-note">Lưu ký ức</button><button class="btn outline" data-action="export-passport">${icon('download')} Tải hộ chiếu</button></div><p class="small muted">Hộ chiếu được lưu trên trình duyệt này. Tải bản sao để giữ lại trước khi đổi thiết bị.</p></section></div>`}
function scanPage(){return `${pageHead('Mở một câu chuyện','Quét để bắt đầu.','Dùng mã của bản trải nghiệm hoặc nhập mã trạm bên dưới.')}<div class="scan-layout"><section class="camera-stage" id="camera-stage"><img src="${asset('031.webp')}" alt="Ảnh mẫu lớp lá trên nền đất tại Củ Chi"><video id="camera-video" autoplay playsinline muted></video><div class="camera-head"><span class="tag" id="camera-status">Ảnh mẫu · Camera chưa bật</span>${icon('scan')}</div><div class="scan-frame"><span class="scan-line"></span></div><div class="camera-bottom"><h2>Một mã. Một câu chuyện.</h2><p id="camera-help">Đặt mã QR trong khung. Camera chỉ bật khi bạn chọn bên dưới.</p><button class="btn cream" data-action="camera">${icon('camera')} Bật camera</button></div></section><section class="scan-panel"><h2>Chậm một nhịp,<br>thấy thêm một điều.</h2>${[['Bật camera','Cho phép ứng dụng sử dụng camera để xem hình và đọc mã nếu trình duyệt hỗ trợ.'],['Hướng vào mã trạm','Bản trải nghiệm dùng mã CC-01 đến CC-06. Không nhận diện vật thể tự động.'],['Mở chuyện & lưu dấu','Khám phá chi tiết rồi hoàn thành thử thách trong câu chuyện.']].map((a,i)=>`<div class="instruction"><span class="circle-no">${i+1}</span><div><strong>${a[0]}</strong><p>${a[1]}</p></div></div>`).join('')}<form id="code-form"><div class="form-row"><label class="field" for="station-code">Nhập mã trạm<input id="station-code" name="code" placeholder="Ví dụ: CC-01" autocomplete="off" maxlength="12" required></label><button class="btn" type="submit">Mở câu chuyện</button></div><div id="code-error" class="form-error" role="alert"></div></form><div class="callout">Chưa có mã? <button class="text-btn" data-action="sample-code">Dùng thử trạm CC-01</button><br>Mã trong app là mã thử nghiệm, chưa gắn với hệ thống QR chính thức của di tích.</div></section></div>`}
const HOTSPOTS=[{title:'Quan sát đường viền',body:'Nhìn nơi bề mặt và màu sắc thay đổi. Đây là một gợi ý quan sát, không phải kết quả nhận diện tự động.'},{title:'Đọc cùng bối cảnh',body:'Đặt chi tiết trong mối liên hệ với cảnh quan xung quanh. Thông tin tại di tích sẽ giúp bạn hiểu rõ hơn.'},{title:'Giữ lại một câu hỏi',body:'Điều gì bức ảnh chưa thể trả lời? Mang câu hỏi ấy đến cuộc trò chuyện với hướng dẫn viên.'}];
function arPage(id){const s=stories.find(x=>x.id===id)||stories[0];return `<a class="back" href="#/story/${s.id}">${icon('back')} Trở lại câu chuyện</a>${pageHead('Lớp khám phá tương tác','Nhìn qua một lớp khác.','Chạm các điểm chú thích trên ảnh để khám phá.')}<div class="ar-stage" id="camera-stage"><img src="${asset(s.image)}" alt="${esc(s.title)}"><video id="camera-video" autoplay playsinline muted></video><div class="ar-3d" id="ar-3d" aria-hidden="true"></div><div class="ar-head"><span class="tag" id="camera-status">AR · Xem trước vật thể 3D · Bật camera để đặt lên mã ${s.code}</span><span class="tag">${s.code}</span></div>${[[33,29],[61,39],[48,53]].map((pos,i)=>`<button class="ar-hotspot ${hotspot===i?'selected':''}" style="left:${pos[0]}%;top:${pos[1]}%" data-action="hotspot" data-index="${i}" aria-label="Điểm chú thích ${i+1}" aria-pressed="${hotspot===i}">${i+1}</button>`).join('')}<div class="ar-info" id="ar-info"><div class="eyebrow">Điểm quan sát 0${hotspot+1}</div><h2>${HOTSPOTS[hotspot].title}</h2><p>${HOTSPOTS[hotspot].body}</p></div></div><div class="ar-details"><div class="note"><h3>Đặt chú thích lên camera</h3><p>Hướng camera vào mã trạm ${s.code}: mô hình 3D của ${esc(window.CuChi3D?.stations?.[s.id]?.short?.toLowerCase()||'điểm dừng')} hiện ra trên mã, các điểm chú thích bám theo vị trí và góc xoay của mã. Khi mất mã, mô hình ẩn đi và điểm trở về vị trí cố định. Mô hình là minh họa, ứng dụng không nhận diện hiện vật.</p><button class="btn" data-action="camera">${icon('camera')} Bật camera AR</button></div><div class="note"><h3>Từ quan sát đến câu chuyện</h3><p>Trở lại chương đang đọc để hoàn thành thử thách và nhận dấu vào hộ chiếu.</p><a class="btn" href="#/story/${s.id}">${icon('book')} Đọc chuyện & nhận dấu</a><a class="btn outline" style="margin-top:12px" href="#/vr/${s.id}">${icon('vr')} Vào cảnh VR của trạm</a><a class="text-btn" style="margin-top:15px" href="#/compare/${s.id}">Thử lớp màu ký ức</a></div></div>`}
function comparePage(id){const s=stories.find(x=>x.id===id)||stories[0];return `<a class="back" href="#/ar/${s.id}">${icon('back')} Lớp khám phá</a>${pageHead('Một ảnh, hai cảm nhận','Lớp màu ký ức','Kéo thanh để so sánh ảnh gốc và cùng ảnh được xử lý màu. Đây không phải cặp ảnh lịch sử trước–sau.')}<div class="compare"><img src="${asset(s.image)}" alt="Ảnh gốc"><div class="cut" id="compare-cut"><img src="${asset(s.image)}" alt="Cùng ảnh với lớp màu sepia"></div><div class="divider" id="compare-divider"></div><span class="label left">Lớp màu ký ức</span><span class="label right">Ảnh gốc</span></div><label class="field" for="compare-range">Tỷ lệ so sánh<input class="range" type="range" id="compare-range" min="0" max="100" value="50"></label>`}
function explorerPage(){if(window.CuChi3D?.supported)return map3dPage();return `${pageHead('Hiểu không gian','Kết nối những điểm nhỏ.','Sơ đồ khái niệm về lối vào, thông khí và không gian dưới đất. Chạm một nhãn để mở câu chuyện liên quan.')}<div class="explorer"><svg viewBox="0 0 900 440" role="img" aria-label="Sơ đồ minh họa các kết nối dưới mặt đất, không theo tỷ lệ thực"><path d="M0 130H900V440H0Z" fill="#c8b79a"/><path d="M0 130H900" stroke="#68734b" stroke-width="8"/><path d="M175 130V270H685M410 130V270M685 270V350H440" fill="none" stroke="#786448" stroke-width="37" stroke-linecap="round" stroke-linejoin="round"/><path d="M175 130V270H685M410 130V270M685 270V350H440" fill="none" stroke="#e8d8b8" stroke-width="25" stroke-linejoin="round"/><rect x="550" y="240" width="130" height="62" rx="15" fill="#e8d8b8"/><text x="27" y="110" font-size="15" fill="#52603d">MẶT ĐẤT</text><g class="diagram-button" role="link" tabindex="0" aria-label="Mở câu chuyện nắp hầm" data-link="story/nap-ham"><rect x="96" y="35" width="160" height="55" rx="4" fill="#263b2d"/><text x="176" y="68" fill="#f3eddf" text-anchor="middle" font-size="18">01 · Lối vào</text></g><path d="M176 90V123" stroke="#263b2d" stroke-dasharray="4 3"/><g class="diagram-button" role="link" tabindex="0" aria-label="Mở câu chuyện lỗ thông hơi" data-link="story/lo-thong-hoi"><rect x="320" y="35" width="180" height="55" rx="4" fill="#263b2d"/><text x="410" y="68" fill="#f3eddf" text-anchor="middle" font-size="18">02 · Thông khí</text></g><path d="M410 90V123" stroke="#263b2d" stroke-dasharray="4 3"/><g class="diagram-button" role="link" tabindex="0" aria-label="Mở câu chuyện lòng địa đạo" data-link="story/long-dia-dao"><rect x="559" y="166" width="210" height="55" rx="4" fill="#263b2d"/><text x="664" y="200" fill="#f3eddf" text-anchor="middle" font-size="18">03 · Không gian</text></g><text x="27" y="410" font-size="14" fill="#5b523f">SƠ ĐỒ MINH HỌA · KHÔNG THEO TỶ LỆ · KHÔNG DÙNG ĐỂ CHỈ ĐƯỜNG</text></svg></div><div class="feature-row"><div class="note"><h3>Quan sát trước, diễn giải sau</h3><p>Sơ đồ làm rõ các mối liên hệ, không thể hiện vị trí hay cấu trúc chính xác của một tuyến địa đạo.</p></div><div class="note"><h3>Tiếp tục bằng một câu chuyện</h3><p>Đi từ khái niệm không gian đến những chi tiết cụ thể trong bộ ảnh.</p><a href="#/story/long-dia-dao" class="btn">Theo một đường đất nhỏ</a></div></div>`}
const STATION_DEPTH={'nap-ham':'Mặt đất → Tầng 1','lo-thong-hoi':'Mặt đất · ống thông xuống Tầng 1','bep-hoang-cam':'Tầng 1 · khoảng 3 m','long-dia-dao':'Tầng 2 · khoảng 6 m','dau-tich':'Mặt đất','loi-rung':'Mặt đất · lối ra'};
function mapInfo(id){const s=stories.find(x=>x.id===id);if(!s)return `<div class="eyebrow">Bản đồ tương tác</div><h3 style="margin-top:12px">Chạm một trạm</h3><p>Chạm nhãn hoặc điểm vàng trên mô hình để xem trạm nằm ở tầng nào và mở câu chuyện, cảnh VR hoặc lớp AR của trạm.</p>`;return `<div class="eyebrow">${s.code} · ${STATION_DEPTH[s.id]||''}</div><h3 style="margin-top:12px">${esc(s.title)}</h3><p>${esc(s.excerpt)}</p><div class="map3d-actions"><a class="btn" href="#/story/${s.id}">${icon('book')} Đọc chuyện</a><a class="btn outline" href="#/vr/${s.id}">${icon('vr')} Vào VR</a><a class="btn outline" href="#/ar/${s.id}">${icon('layers')} Lớp AR</a></div>`}
function map3dPage(){const layer=(k,t)=>`<button class="chip ${mapLayers[k]?'active':''}" data-action="map-layer" data-value="${k}" aria-pressed="${mapLayers[k]}">${t}</button>`;return `${pageHead('Hiểu không gian','Bản đồ 3D địa đạo.','Kéo để xoay, chụm hoặc cuộn để phóng to, chạm một trạm để xem chi tiết. Mô hình minh họa ba tầng địa đạo, không theo tỷ lệ và không dùng để chỉ đường.')}<div class="map3d-layout"><div class="map3d-stage" id="camera-stage"><video id="camera-video" autoplay playsinline muted></video><div class="map3d" id="map3d"></div><div class="ar-head"><span class="tag" id="camera-status">Mô hình 3D · Kéo để xoay</span><button class="tag map3d-reset" data-action="map-reset">Góc nhìn ban đầu</button></div></div><aside class="map3d-side"><div class="note"><h3>Lớp hiển thị</h3><div class="filters" style="margin:14px 0 0">${layer('surface','Mặt đất')}${layer('l1','Tầng 1')}${layer('l2','Tầng 2')}${layer('l3','Tầng 3')}${layer('route','Đường hành trình')}</div></div><div class="note" id="map-info">${mapInfo(map3dSelected)}</div><div class="note"><h3>Đặt bản đồ lên mã (AR)</h3><p>Bật camera rồi hướng vào một mã trạm bất kỳ (CC-01 … CC-06): mô hình địa đạo hiện ra trên mã và bám theo khi bạn di chuyển.</p><button class="btn" data-action="camera">${icon('camera')} Bật AR bản đồ</button></div></aside></div><div class="filters station-chips">${stories.map(s=>`<button class="chip ${map3dSelected===s.id?'active':''}" data-action="map-select" data-id="${s.id}">${s.code} · ${esc(s.title)}</button>`).join('')}</div>`}
function vrPage(id){const s=stories.find(x=>x.id===id)||stories[0];const ok=window.CuChi3D?.supported;return `<a class="back" href="#/story/${s.id}">${icon('back')} Trở lại câu chuyện</a>${pageHead('Cảnh VR · '+s.code,esc(s.title),'Kéo để nhìn quanh, hoặc bật con quay rồi nghiêng máy. Chạm các điểm số để nghe giải thích. Cảnh dựng 3D minh họa, không theo tỷ lệ thật.')}<div class="vr-stage" id="vr-stage">${ok?'<div class="vr-view" id="vr-view"></div>':`<img src="${asset(s.image)}" alt="${esc(s.title)}" style="position:absolute;inset:0;width:100%;height:100%;object-fit:cover;opacity:.7">`}<div class="ar-head"><span class="tag">VR · Mô hình minh họa</span><span class="tag">${s.code}</span></div><div class="ar-info" id="vr-info"><div class="eyebrow">Nhìn quanh</div><h2>${ok?'Chạm một điểm số':'Trình duyệt chưa hỗ trợ 3D'}</h2><p>${ok?'Mỗi điểm sáng là một chi tiết để quan sát.':'Thiết bị này chưa bật WebGL nên chưa hiển thị được cảnh VR. Bạn vẫn có thể đọc câu chuyện và xem lớp AR.'}</p></div>${s.id==='long-dia-dao'&&ok?`<div class="vr-walk"><button class="btn cream small" data-walk="1">${icon('move')} Giữ để đi tới</button><button class="btn ghost small" data-walk="-1">Lùi lại</button></div>`:''}</div>${ok?`<div class="vr-tools"><button class="btn outline" data-action="vr-gyro" aria-pressed="false">${icon('move')} Bật con quay</button><button class="btn outline" data-action="vr-stereo" aria-pressed="false">${icon('vr')} Chế độ kính VR</button><a class="btn" href="#/story/${s.id}">${icon('book')} Đọc chuyện & nhận dấu</a></div><div class="filters" id="vr-spots"></div>`:''}<div class="section-heading"><h3>Cảnh VR khác</h3></div><div class="filters">${stories.map(x=>`<a class="chip ${x.id===s.id?'active':''}" href="#/vr/${x.id}">${x.code} · ${esc(x.title)}</a>`).join('')}</div><p class="small muted">Chế độ kính VR chia đôi màn hình cho kính VR dạng hộp gắn điện thoại. Xoay ngang máy và bật con quay để nhìn theo chuyển động đầu.</p>`}
function vrInfo(h,i){return `<div class="eyebrow">Điểm ${i+1}</div><h2>${esc(h.t)}</h2><p>${esc(h.d)}</p>`}
function unmount3D(){if(view3d){try{view3d.dispose()}catch{}view3d=null}vrGyro=false;vrStereo=false;if(document.fullscreenElement&&document.exitFullscreen)document.exitFullscreen().catch(()=>{})}
function mount3D(parts){const C=window.CuChi3D;if(!C?.supported)return;try{if(parts[0]==='explorer'){const el=document.querySelector('#map3d');if(!el)return;view3d=C.createMap(el,{onSelect:id=>{map3dSelected=id;const info=document.querySelector('#map-info');if(info)info.innerHTML=mapInfo(id);document.querySelectorAll('[data-action="map-select"]').forEach(b=>b.classList.toggle('active',b.dataset.id===id))}});Object.entries(mapLayers).forEach(([k,v])=>k==='route'?view3d.setRoute(v):view3d.setLayer(k,v));if(map3dSelected)view3d.select(map3dSelected)}
else if(parts[0]==='vr'){const el=document.querySelector('#vr-view');if(!el)return;const s=stories.find(x=>x.id===parts[1])||stories[0];view3d=C.createVR(el,{scene:s.id,onHotspot:(h,i)=>{const info=document.querySelector('#vr-info');if(info)info.innerHTML=vrInfo(h,i);document.querySelectorAll('[data-action="vr-hotspot"]').forEach((b,k)=>b.classList.toggle('active',k===i))}});const list=document.querySelector('#vr-spots');if(list)list.innerHTML=view3d.hotspots.map((h,i)=>`<button class="chip" data-action="vr-hotspot" data-index="${i}">${i+1} · ${esc(h.t)}</button>`).join('')}
else if(parts[0]==='ar'){const el=document.querySelector('#ar-3d');if(!el)return;const s=stories.find(x=>x.id===parts[1])||stories[0];view3d=C.createARObject(el,{id:s.id})}}catch{view3d=null}}
function adminPage(editId){const s=stories.find(x=>x.id===editId);return `${pageHead('Không gian biên tập','Bàn kể chuyện','Chăm chút từng chương, câu hỏi và trải nghiệm tại điểm dừng.')}<div class="admin-layout"><aside class="admin-nav"><div class="eyebrow">Củ Chi Stories</div><h3>Sổ biên tập</h3><div class="admin-links">${[['overview','grid','Tổng quan'],['content','book','Câu chuyện'],['flow','map','Luồng trải nghiệm'],['ar','scan','Camera & AR']].map(([k,i,t])=>`<button class="${adminTab===k?'active':''}" data-action="admin-tab" data-value="${k}">${icon(i)} ${t}</button>`).join('')}</div><p>${serverMode?'Đang lưu nội dung qua máy chủ cục bộ.':'Chế độ HTML: nội dung chỉnh sửa lưu trên trình duyệt này.'}<br>Đây là bàn biên tập thử nghiệm, chưa có tài khoản hay phân quyền.</p></aside><section>${s?editor(s):adminContent()}</section></div>`}
function adminContent(){if(adminTab==='flow')return `<h2>Một hành trình liền mạch</h2><div class="flow-list">${[['01','Chọn hành trình'],['02','Đọc / nghe chuyện'],['03','Khám phá & trả lời'],['04','Nhận dấu & ghi nhớ']].map(a=>`<div><b>${a[0]}</b>${a[1]}</div>`).join('')}</div><div class="note"><h3>Tiến trình có thể tiếp nối</h3><p>Mỗi trạm chỉ được cộng 50 điểm một lần. Người đọc có thể đổi hành trình, quay lại các chương và giữ nguyên dấu đã nhận.</p><p>Hộ chiếu là dữ liệu cá nhân trên trình duyệt. Nội dung câu chuyện lưu trên máy chủ khi chạy bản có máy chủ cục bộ.</p></div>`;
if(adminTab==='ar')return `<h2>Camera & lớp khám phá</h2><div class="table-wrap" style="margin-top:25px"><table class="admin-table"><thead><tr><th>Tính năng</th><th>Trạng thái</th></tr></thead><tbody><tr><td>Xin quyền và hiển thị camera</td><td><span class="tag green">Đã triển khai</span></td></tr><tr><td>Đọc QR (BarcodeDetector hoặc jsQR offline)</td><td><span class="tag green">Đã triển khai</span></td></tr><tr><td>Nhập mã CC-01 … CC-06</td><td><span class="tag green">Đã triển khai</span></td></tr><tr><td>Hotspot bám theo mã trạm trên camera (marker 2D)</td><td><span class="tag green">Đã triển khai</span></td></tr><tr><td>Vật thể 3D minh họa hiện trên mã trạm</td><td><span class="tag green">Đã triển khai</span></td></tr><tr><td>Bản đồ 3D địa đạo tương tác, đặt lên mã (AR)</td><td><span class="tag green">Đã triển khai</span></td></tr><tr><td>Cảnh VR từng trạm (mô hình 3D minh họa, con quay, kính VR)</td><td><span class="tag green">Đã triển khai</span></td></tr><tr><td>Nhận diện hiện vật, neo không gian 3D</td><td><span class="tag red">Chưa tích hợp</span></td></tr><tr><td>Panorama 360° chụp thực / mô hình quét thực</td><td>Cần tư liệu và bộ máy hiển thị</td></tr></tbody></table></div><div class="note" style="margin-top:25px"><h3>Sẵn sàng nối tiếp phần AR</h3><p>Ảnh, mã trạm và ID câu chuyện đã tách rõ. Có tài liệu bàn giao kèm mã nguồn để Claude có thể nối engine AR vào luồng hiện tại.</p><a class="btn" href="#/scan">Mở màn quét</a><a class="btn outline" href="#/ar/nap-ham">Mở lớp AR mẫu</a></div>`;
return `${adminTab==='overview'?`<div class="stat-cards"><div class="stat-card"><span>Chương nội dung</span><strong>${stories.length}</strong><span>trong bản trải nghiệm</span></div><div class="stat-card"><span>Nhiệm vụ</span><strong>${stories.length}</strong><span>gắn với câu chuyện</span></div><div class="stat-card"><span>Dấu đã nhận</span><strong>${state.completed.length}</strong><span>trên trình duyệt này</span></div></div>`:''}<div class="section-heading"><div><h2 style="font-size:30px">Các chương chuyện</h2><p>Chỉnh nội dung và xem ngay trải nghiệm của người đọc.</p></div><button class="btn outline small" data-action="export-content">${icon('download')} Xuất nội dung</button></div><div class="table-wrap"><table class="admin-table"><thead><tr><th>Điểm dừng</th><th>Nhiệm vụ</th><th>Mã quét</th><th></th></tr></thead><tbody>${stories.map(s=>`<tr><td><div class="row"><img src="${asset(s.image)}" alt=""><div><strong>${esc(s.title)}</strong><small>${esc(s.category)} · ${s.minutes} phút</small></div></div></td><td>50 điểm</td><td>${s.code}</td><td><a class="icon-btn" href="#/admin/edit/${s.id}" aria-label="Sửa ${esc(s.title)}">${icon('edit')}</a></td></tr>`).join('')}</tbody></table></div><p class="admin-status">${serverMode?'Nội dung được lưu trong cơ sở dữ liệu của máy chủ cục bộ.':'Chế độ HTML độc lập · Thay đổi lưu trên trình duyệt này.'} Không có số liệu khách tham quan giả lập.</p><div class="callout">Nội dung diễn giải hiện là bản biên tập thử nghiệm. Cần thẩm định lịch sử và thống nhất với đơn vị quản lý di tích trước khi sử dụng chính thức.</div>`}
function editor(s){return `<form id="editor-form" class="editor" data-id="${s.id}"><div class="editor-head"><div><span class="small muted">${s.code} · Chỉnh sửa chương</span><h2>${esc(s.title)}</h2></div><button class="btn" type="submit">Lưu nội dung</button></div><label class="field">Tên câu chuyện<input name="title" value="${esc(s.title)}" required maxlength="100"></label><label class="field">Mô tả thẻ câu chuyện<textarea name="excerpt" required maxlength="400" style="min-height:90px">${esc(s.excerpt)}</textarea></label><label class="field">Lời dẫn<textarea name="lead" required maxlength="400" style="min-height:90px">${esc(s.lead)}</textarea></label><label class="field">Nội dung câu chuyện<textarea name="body" required maxlength="12000" style="min-height:260px">${esc(s.body)}</textarea></label><div class="editor-grid"><label class="field">Thời gian đọc (phút)<input type="number" name="minutes" min="1" max="60" value="${s.minutes}" required></label><label class="field">Tên dấu<input name="stamp" required value="${esc(s.stamp)}" maxlength="24"></label></div><label class="field">Câu hỏi thử thách<input name="question" value="${esc(s.question)}" required maxlength="300"></label>${s.options.map((o,i)=>`<label class="field">Lựa chọn ${String.fromCharCode(65+i)}<input name="option${i}" value="${esc(o)}" required maxlength="300"></label>`).join('')}<label class="field">Đáp án đúng<select name="answer">${s.options.map((o,i)=>`<option value="${i}" ${i===s.answer?'selected':''}>Lựa chọn ${String.fromCharCode(65+i)}</option>`).join('')}</select></label><label class="field">Giải thích đáp án<textarea name="explanation" required maxlength="1000" style="min-height:100px">${esc(s.explanation)}</textarea></label><div class="row" style="flex-wrap:wrap"><button class="btn" type="submit">Lưu nội dung</button><a class="btn outline" href="#/story/${s.id}">Xem chương hiện tại</a><a class="text-btn" href="#/admin">Quay lại</a></div><div id="editor-status" class="admin-status" role="status"></div></form>`}
function notFound(){return `<div class="empty"><h2>Chưa tìm thấy điểm dừng này</h2><p>Hãy trở lại thư viện để chọn một câu chuyện.</p><a href="#/stories" class="btn" style="margin-top:20px">Mở thư viện</a></div>`}
function stopCamera(){cameraGeneration++;if(stream){stream.getTracks().forEach(t=>t.stop());stream=null}clearTimeout(scanTimer);scanTimer=null;arPose=null}
function stopAudio(){if('speechSynthesis'in window)window.speechSynthesis.cancel();audioActive=false}
function render(){stopCamera();stopAudio();unmount3D();route=decodeURI(location.hash.replace(/^#\/?/,'')).replace(/\/$/,'');const parts=route.split('/');let content;switch(parts[0]){case '':content=home();break;case 'journey':content=journeys();break;case 'stories':content=library();break;case 'story':content=storyPage(parts[1]);break;case 'map':content=mapPage();break;case 'passport':content=passportPage();break;case 'scan':content=scanPage();break;case 'ar':content=arPage(parts[1]);break;case 'compare':content=comparePage(parts[1]);break;case 'explorer':content=explorerPage();break;case 'vr':content=vrPage(parts[1]);break;case 'admin':content=adminPage(parts[2]);break;default:content=notFound()}app.innerHTML=header()+`<main id="main" class="shell view-enter" tabindex="-1">${content}${footer()}</main>`+bottomNav();mount3D(parts);document.title=(parts[0]==='vr'?'VR · ':'')+(parts[0]==='story'?(stories.find(x=>x.id===parts[1])?.title||'Câu chuyện')+' · ':'')+'Củ Chi Stories';}
function dialog(html){modal.innerHTML=html;modal.showModal()}
function closeDialog(){modal.close()}
function reward(s){dialog(`<div class="reward"><div class="seal"><div>CỦ CHI<b>✦</b>${esc(s.stamp)}</div></div><span class="eyebrow" style="justify-content:center">+50 điểm khám phá</span><h2 style="margin-top:15px">Một dấu đã được giữ lại.</h2><p>${esc(s.explanation)}</p><p>${state.completed.length}/6 dấu trong hộ chiếu của bạn.</p><button class="btn" data-action="reward-next">${currentJourney().ids.some(id=>!state.completed.includes(id))?'Đến câu chuyện tiếp theo':'Xem hộ chiếu của tôi'}</button><button class="text-btn" style="margin-top:17px" data-action="close">Ở lại câu chuyện này</button></div>`)}
function download(name,data,type){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([data],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),5000)}
function validateCode(value){const m=String(value??'').toUpperCase().match(/(?:^|[^A-Z0-9])CC-?(\d{2})(?!\d)/);if(!m)return null;const code='CC-'+m[1];return stories.find(s=>s.code===code)||null}
// ---- Camera · đọc QR · AR bám theo mã trạm ----
// Bộ đọc QR: BarcodeDetector của trình duyệt nếu hỗ trợ, nếu không dùng jsQR đóng gói sẵn (assets/jsQR.js, chạy offline).
// AR: khi camera thấy đúng mã trạm của câu chuyện, các điểm chú thích được neo theo vị trí, kích thước và góc xoay của mã.
// Đây là bám theo mã in (marker), không phải nhận diện hiện vật. Mất mã thì điểm trở về vị trí cố định.
const AR_DEFAULT=[[33,29],[61,39],[48,53]];
// Vị trí điểm tính theo cạnh mã, từ tâm mã (u: sang phải, v: xuống dưới): ngay ngoài góc trên-trái, cạnh phải, cạnh dưới.
const AR_OFFSETS=[[-0.8,-0.75],[0.85,-0.15],[0.05,0.85]];
const AR_LOST_MS=800;
let arPose=null,qrCanvas=null;
function setCameraStatus(text){const el=document.querySelector('#camera-status');if(el)el.textContent=text}
async function createQrReader(){try{if('BarcodeDetector'in window&&(await BarcodeDetector.getSupportedFormats()).includes('qr_code')){const detector=new BarcodeDetector({formats:['qr_code']});return async video=>(await detector.detect(video)).map(c=>({text:c.rawValue,corners:c.cornerPoints}))}}catch{}
if(typeof window.jsQR!=='function')return null;qrCanvas=qrCanvas||document.createElement('canvas');const ctx=qrCanvas.getContext('2d',{willReadFrequently:true});
return async video=>{const vw=video.videoWidth,vh=video.videoHeight;if(!vw||!vh)return[];const k=Math.min(1,720/Math.max(vw,vh)),w=Math.round(vw*k),h=Math.round(vh*k);if(qrCanvas.width!==w||qrCanvas.height!==h){qrCanvas.width=w;qrCanvas.height=h}ctx.drawImage(video,0,0,w,h);const found=window.jsQR(ctx.getImageData(0,0,w,h).data,w,h,{inversionAttempts:'attemptBoth'});if(!found)return[];const L=found.location,pt=q=>({x:q.x/k,y:q.y/k});return[{text:found.data,corners:[pt(L.topLeftCorner),pt(L.topRightCorner),pt(L.bottomRightCorner),pt(L.bottomLeftCorner)]}]}}
// Toạ độ khung hình video → toạ độ khung hiển thị (video dùng object-fit: cover).
function videoToStage(video,stage,p){const vw=video.videoWidth,vh=video.videoHeight,W=stage.clientWidth,H=stage.clientHeight,s=Math.max(W/vw,H/vh);return{x:(W-vw*s)/2+p.x*s,y:(H-vh*s)/2+p.y*s}}
function markerPose(video,stage,corners){const [tl,tr,br,bl]=corners.map(c=>videoToStage(video,stage,c));return{cx:(tl.x+tr.x+br.x+bl.x)/4,cy:(tl.y+tr.y+br.y+bl.y)/4,ux:((tr.x-tl.x)+(br.x-bl.x))/2,uy:((tr.y-tl.y)+(br.y-bl.y))/2,vx:((bl.x-tl.x)+(br.x-tr.x))/2,vy:((bl.y-tl.y)+(br.y-tr.y))/2}}
function placeHotspots(stage,pose){const spots=stage.querySelectorAll('.ar-hotspot');if(!pose){spots.forEach((el,i)=>{el.style.left=AR_DEFAULT[i][0]+'%';el.style.top=AR_DEFAULT[i][1]+'%'});return}
// Làm mượt nhẹ để điểm không rung theo từng khung hình.
const prev=arPose,a=prev?.5:1,mix=k=>prev?prev[k]+(pose[k]-prev[k])*a:pose[k];const P={cx:mix('cx'),cy:mix('cy'),ux:mix('ux'),uy:mix('uy'),vx:mix('vx'),vy:mix('vy')};arPose=P;
const info=stage.querySelector('#ar-info'),bottom=(info?info.offsetTop:stage.clientHeight)-8;
// Giữ điểm trong khung và phía trên khung chú thích để không che chữ.
spots.forEach((el,i)=>{const [ox,oy]=AR_OFFSETS[i],r=el.offsetWidth/2,x=P.cx+ox*P.ux+oy*P.vx,y=P.cy+ox*P.uy+oy*P.vy;el.style.left=Math.max(0,Math.min(stage.clientWidth-2*r,x-r))+'px';el.style.top=Math.max(0,Math.min(bottom-2*r,y-r))+'px'})}
function cameraError(e){if(!window.isSecureContext||e?.name==='SecurityError')return 'Camera cần trang mở qua HTTPS, localhost hoặc file trên máy.';if(e?.name==='NotAllowedError')return 'Camera chưa được cấp quyền. Bạn có thể nhập mã trạm.';if(e?.name==='NotFoundError'||e?.name==='OverconstrainedError')return 'Không tìm thấy camera trên thiết bị.';if(e?.name==='NotReadableError')return 'Camera đang được ứng dụng khác sử dụng.';return 'Trình duyệt này chưa hỗ trợ camera. Bạn vẫn có thể nhập mã trạm.'}
// Màn quét: vật thể 3D của trạm bật lên trên mã khoảng 1,6 giây rồi mở chương.
function revealStation(s,c,read,video,stage,generation){let obj=null;if(window.CuChi3D?.supported&&c.corners?.length===4){const holder=document.createElement('div');holder.className='ar-3d';stage.appendChild(holder);try{obj=window.CuChi3D.createARObject(holder,{id:s.id});obj.setLive(true);obj.setPose(markerPose(video,stage,c.corners))}catch{obj=null}}
const until=performance.now()+(obj?1600:0);const done=()=>{obj?.dispose();stopCamera();toast('Đã mở trạm '+s.code);go('story/'+s.id)};
const follow=async()=>{if(generation!==cameraGeneration){obj?.dispose();return}if(performance.now()>=until)return done();try{const hit=(await read(video)).find(x=>validateCode(x.text)?.id===s.id&&x.corners?.length===4);if(hit&&generation===cameraGeneration)obj?.setPose(markerPose(video,stage,hit.corners))}catch{}scanTimer=setTimeout(follow,60)};follow()}
// Màn bản đồ 3D: đặt mô hình địa đạo lên bất kỳ mã trạm nào camera thấy.
function trackMapMarker(read,video,stage,generation){if(!read){setCameraStatus('Camera đang bật · Trình duyệt chưa đọc được mã');return}view3d?.setAR?.(null,true);setCameraStatus('Hướng vào một mã trạm để đặt bản đồ');let pose=null,lastSeen=0,code='';
const tick=async()=>{if(!stream||generation!==cameraGeneration)return;let hit=null;try{hit=(await read(video)).find(x=>validateCode(x.text)&&x.corners?.length===4)||null}catch{}if(generation!==cameraGeneration)return;const now=performance.now();
if(hit){const p=markerPose(video,stage,hit.corners);pose=pose?Object.fromEntries(Object.keys(p).map(k=>[k,pose[k]+(p[k]-pose[k])*.5])):p;lastSeen=now;code=validateCode(hit.text).code;view3d?.setAR?.(pose,true);setCameraStatus('Bản đồ đang bám mã '+code)}
else if(pose&&now-lastSeen>AR_LOST_MS){pose=null;view3d?.setAR?.(null,true);setCameraStatus('Mất dấu mã '+code+' · Hướng lại vào mã trạm')}
scanTimer=setTimeout(tick,pose?60:150)};tick()}
async function startCamera(){if(stream){stopCamera();render();return}const stage=document.querySelector('#camera-stage'),help=document.querySelector('#camera-help');const generation=++cameraGeneration;const isAr=route.startsWith('ar/');
try{if(!navigator.mediaDevices?.getUserMedia)throw new Error('unsupported');setCameraStatus('Đang chờ quyền camera…');const ask=video=>navigator.mediaDevices.getUserMedia({video,audio:false});let newStream;try{newStream=await ask({facingMode:{ideal:'environment'},width:{ideal:1280},height:{ideal:720}})}catch(e){if(e.name!=='OverconstrainedError')throw e;newStream=await ask(true)}
if(generation!==cameraGeneration){newStream.getTracks().forEach(t=>t.stop());return}stream=newStream;newStream.getVideoTracks()[0]?.addEventListener('ended',()=>{if(stream===newStream){stopCamera();render();toast('Camera đã ngắt kết nối.')}});
const video=document.querySelector('#camera-video');video.srcObject=stream;await video.play();if(generation!==cameraGeneration)return;stage.classList.add('live');document.querySelectorAll('[data-action="camera"]').forEach(b=>b.innerHTML=icon('camera')+' Tắt camera');
const read=await createQrReader();if(generation!==cameraGeneration)return;
if(route==='explorer')return trackMapMarker(read,video,stage,generation);
if(isAr){const s=stories.find(x=>x.id===route.split('/')[1])||stories[0];if(!read){setCameraStatus('Camera trực tiếp · Chú thích cố định');return}view3d?.setLive?.(true);setCameraStatus('Đang tìm mã '+s.code+' · Chú thích cố định');let lastSeen=0,tracking=false;
const tick=async()=>{if(!stream||generation!==cameraGeneration)return;let mine=null,other=null;try{for(const c of await read(video)){const hit=validateCode(c.text);if(hit?.id===s.id&&c.corners?.length===4)mine=c;else if(hit)other=hit}}catch{}if(generation!==cameraGeneration)return;const now=performance.now();
if(mine){lastSeen=now;placeHotspots(stage,markerPose(video,stage,mine.corners));view3d?.setPose?.(arPose);if(!tracking){tracking=true;navigator.vibrate?.(30)}setCameraStatus('Đang bám mã '+s.code+' · Vật thể & chú thích theo mã')}
else if(tracking&&now-lastSeen>AR_LOST_MS){tracking=false;arPose=null;placeHotspots(stage,null);view3d?.setPose?.(null);setCameraStatus('Mất dấu mã '+s.code+' · Chú thích cố định')}
else if(!tracking&&other)setCameraStatus('Đây là mã '+other.code+' của trạm khác · Hướng vào mã '+s.code);
scanTimer=setTimeout(tick,tracking?60:150)};tick();return}
setCameraStatus(read?'Camera đang bật · Đang tìm mã QR':'Camera đang bật · Nhập mã bên dưới');if(help)help.textContent=read?'Hướng vào mã QR chứa CC-01 đến CC-06.':'Trình duyệt này chưa đọc được QR trực tiếp. Hãy nhập mã trạm bên dưới.';if(!read)return;
const detect=async()=>{if(!stream||generation!==cameraGeneration)return;let foreign=false;try{for(const c of await read(video)){const s=validateCode(c.text);if(s){setCameraStatus('Đã đọc mã '+s.code+' · '+s.title);navigator.vibrate?.(60);revealStation(s,c,read,video,stage,generation);return}foreign=true}}catch{}if(generation!==cameraGeneration)return;if(foreign)setCameraStatus('Mã QR này không phải mã trạm CC-01 … CC-06');scanTimer=setTimeout(detect,250)};detect()}
catch(e){if(generation!==cameraGeneration)return;stopCamera();setCameraStatus('Chưa thể mở camera');if(help)help.textContent='Bạn vẫn có thể nhập mã trạm để tiếp tục.';toast(cameraError(e))}}
function speak(s,button){if(!('speechSynthesis'in window)){toast('Thiết bị này chưa hỗ trợ đọc văn bản.');return}if(audioActive){stopAudio();button.querySelector('span').textContent='Nghe câu chuyện';return}const speech=new SpeechSynthesisUtterance(s.title+'. '+s.lead+'. '+s.body);speech.lang='vi-VN';speech.rate=.9;const voice=window.speechSynthesis.getVoices().find(v=>v.lang.startsWith('vi'));if(voice)speech.voice=voice;speech.onend=()=>{audioActive=false;const l=document.querySelector('#audio-label');if(l)l.textContent='Nghe câu chuyện'};speech.onerror=()=>{audioActive=false;toast('Không thể phát giọng đọc trên thiết bị này.');const l=document.querySelector('#audio-label');if(l)l.textContent='Nghe câu chuyện'};audioActive=true;button.querySelector('span').textContent='Dừng giọng đọc';window.speechSynthesis.speak(speech);if(!voice)toast('Đang dùng giọng đọc của thiết bị; chất lượng tiếng Việt tùy trình duyệt.')}
document.addEventListener('click',async e=>{if(e.target.closest('.skip')){e.preventDefault();document.querySelector('#main').focus();return}const link=e.target.closest('[data-link]');if(link){go(link.dataset.link);return}const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;switch(a){case 'journey':state.journey=+b.dataset.index;persist();render();break;case 'start':state.started=true;persist();go('story/'+currentStory().id);break;case 'filter':filter=b.dataset.value;render();break;case 'map-pin':selectedMap=b.dataset.id;render();break;case 'answer':quizChoice=+b.dataset.index;quizFeedback='';{const y=scrollY;render();scrollTo(0,y)}break;case 'submit':{const s=stories.find(s=>s.id===b.dataset.id);if(quizChoice===null)return;if(quizChoice!==s.answer){quizFeedback='Chưa đúng rồi. Hãy đọc lại đoạn chuyện và thử chọn một góc nhìn khác.';const y=scrollY;render();scrollTo(0,y)}else{quizFeedback=s.explanation;const isNew=!state.completed.includes(s.id);if(isNew){state.completed.push(s.id);state.started=true;persist()}const y=scrollY;render();scrollTo(0,y);if(isNew)reward(s);else toast('Đúng rồi! Dấu tại trạm này đã có trong hộ chiếu.')}break}case 'reward-next':closeDialog();quizChoice=null;quizFeedback='';go(currentJourney().ids.some(id=>!state.completed.includes(id))?'story/'+currentStory().id:'passport');break;case 'save-note':state.notes=document.querySelector('#memory-note').value;persist();toast('Đã lưu điều bạn muốn nhớ.');break;case 'export-passport':{state.notes=document.querySelector('#memory-note').value;persist();download('Ho-chieu-ky-uc-Cu-Chi.txt','CỦ CHI STORIES — HỘ CHIẾU KÝ ỨC\n\n'+state.completed.length+'/6 dấu · '+score()+' điểm\n\n'+stories.map(s=>(state.completed.includes(s.id)?'✓':'○')+' '+s.title+' — '+s.stamp).join('\n')+'\n\nMỘT ĐIỀU TÔI MUỐN NHỚ\n'+state.notes,'text/plain;charset=utf-8');break}case 'camera':await startCamera();break;case 'sample-code':document.querySelector('#station-code').value='CC-01';document.querySelector('#code-form').requestSubmit();break;case 'hotspot':hotspot=+b.dataset.index;document.querySelector('#ar-info').innerHTML=`<div class="eyebrow">Điểm quan sát 0${hotspot+1}</div><h2>${HOTSPOTS[hotspot].title}</h2><p>${HOTSPOTS[hotspot].body}</p>`;document.querySelectorAll('.ar-hotspot').forEach((el,i)=>{el.classList.toggle('selected',i===hotspot);el.setAttribute('aria-pressed',String(i===hotspot))});break;case 'audio':speak(stories.find(s=>s.id===b.dataset.id),b);break;case 'map-layer':{const k=b.dataset.value;mapLayers[k]=!mapLayers[k];b.classList.toggle('active',mapLayers[k]);b.setAttribute('aria-pressed',String(mapLayers[k]));if(k==='route')view3d?.setRoute?.(mapLayers[k]);else view3d?.setLayer?.(k,mapLayers[k]);break}case 'map-select':map3dSelected=b.dataset.id;view3d?.select?.(map3dSelected);document.querySelector('#map-info').innerHTML=mapInfo(map3dSelected);document.querySelectorAll('[data-action="map-select"]').forEach(x=>x.classList.toggle('active',x===b));break;case 'map-reset':view3d?.reset?.();break;case 'vr-hotspot':view3d?.activate?.(+b.dataset.index);break;case 'vr-gyro':{if(!view3d?.setGyro)break;const want=!vrGyro;const ok=await view3d.setGyro(want);vrGyro=want&&ok;b.setAttribute('aria-pressed',String(vrGyro));b.innerHTML=icon('move')+(vrGyro?' Tắt con quay':' Bật con quay');if(want&&!ok)toast('Thiết bị hoặc trình duyệt chưa cho dùng con quay. Bạn vẫn có thể kéo để nhìn quanh.');break}case 'vr-stereo':{if(!view3d?.setStereo)break;vrStereo=!vrStereo;view3d.setStereo(vrStereo);b.setAttribute('aria-pressed',String(vrStereo));b.innerHTML=icon('vr')+(vrStereo?' Thoát kính VR':' Chế độ kính VR');const st=document.querySelector('#vr-stage');if(vrStereo){st?.requestFullscreen?.().then(()=>screen.orientation?.lock?.('landscape').catch(()=>{})).catch(()=>{});if(!vrGyro)toast('Bật con quay để nhìn theo chuyển động đầu khi đeo kính.')}else if(document.fullscreenElement)document.exitFullscreen().catch(()=>{});break}case 'admin-tab':adminTab=b.dataset.value;go('admin');break;case 'export-content':download('cuchi-content.json',JSON.stringify(stories,null,2),'application/json');break;case 'close':closeDialog();break;case 'about':dialog(`<h2>Đi để hiểu. Nhớ để kể.</h2><p>Củ Chi Stories là bản trải nghiệm thiết kế độc lập, lấy cảm hứng từ chất liệu và sắc màu của không gian Việt hoài niệm. Không phải ứng dụng chính thức của di tích hay sản phẩm liên kết với Cộng Cà Phê.</p><p>Ảnh địa điểm đến từ bộ ảnh bạn đã cung cấp. Câu chuyện diễn giải cần được thẩm định trước khi phát hành. Sơ đồ, điểm AR và thời gian đọc phục vụ trải nghiệm mẫu.</p><p>Camera chỉ được yêu cầu khi bạn bật. Hình ảnh camera không được ứng dụng gửi lên máy chủ. Hộ chiếu lưu trên trình duyệt này.</p><div class="dialog-actions"><button class="btn" data-action="close">Đã hiểu</button></div>`);break;case 'credits':dialog(`<h2>Ảnh & chất liệu</h2><p>Ảnh Củ Chi lấy từ bộ CuChi_100_Images.zip bạn cung cấp. Logo Củ Chi Stories được tạo riêng bằng công cụ tạo ảnh tích hợp.</p><div class="attribution">${(window.CUCHI_CREDITS||[]).map(x=>`<p><strong>${esc(x.name)}</strong><br>${esc(x.artist)} · ${esc(x.license)}<br><a href="${esc(x.url)}" target="_blank" rel="noopener">Trang nguồn ảnh</a></p>`).join('')||'<p>Đối chiếu tác giả, giấy phép và trang nguồn trong assets/source-manifest.csv của bộ mã nguồn.</p>'}</div><div class="dialog-actions"><button class="btn" data-action="close">Đóng</button></div>`);break;}});
document.addEventListener('submit',async e=>{if(e.target.id==='code-form'){e.preventDefault();const s=validateCode(new FormData(e.target).get('code'));if(s){quizChoice=null;quizFeedback='';go('story/'+s.id)}else document.querySelector('#code-error').textContent='Chưa có mã này. Hãy nhập từ CC-01 đến CC-06.'}if(e.target.id==='editor-form'){e.preventDefault();const form=e.target,fd=new FormData(form),s=stories.find(s=>s.id===form.dataset.id);const changed={...s};for(const k of ['title','excerpt','lead','body','stamp','question','explanation'])changed[k]=String(fd.get(k)).trim();changed.minutes=+fd.get('minutes');changed.answer=+fd.get('answer');changed.options=[0,1,2].map(i=>String(fd.get('option'+i)).trim());const next=stories.map(x=>x.id===s.id?changed:x);const status=document.querySelector('#editor-status');form.querySelectorAll('button[type="submit"]').forEach(x=>x.disabled=true);status.textContent='Đang lưu…';try{if(serverMode){const res=await fetch('/api/content',{method:'PUT',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify(next)});if(!res.ok)throw new Error('save');}else localStorage.setItem(STORE+'-content',JSON.stringify(next));stories=next;status.textContent=serverMode?'Đã lưu nội dung vào máy chủ cục bộ.':'Đã lưu nội dung trên trình duyệt này.';toast('Đã lưu. Câu chuyện và thử thách đã cập nhật.')}catch{status.textContent='Chưa lưu được. Nội dung đang sửa vẫn còn ở đây; hãy thử lại.'}finally{form.querySelectorAll('button[type="submit"]').forEach(x=>x.disabled=false)}}});
document.addEventListener('input',e=>{if(e.target.id==='compare-range'){document.querySelector('#compare-cut').style.clipPath=`inset(0 ${100-e.target.value}% 0 0)`;document.querySelector('#compare-divider').style.left=e.target.value+'%'}});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-link]')){e.preventDefault();go(e.target.dataset.link)}});
modal.addEventListener('click',e=>{if(e.target===modal&&e.clientX&&(e.clientX<modal.getBoundingClientRect().left||e.clientX>modal.getBoundingClientRect().right||e.clientY<modal.getBoundingClientRect().top||e.clientY>modal.getBoundingClientRect().bottom))closeDialog()});
document.addEventListener('pointerdown',e=>{const w=e.target.closest('[data-walk]');if(w&&view3d?.setWalk){e.preventDefault();view3d.setWalk(+w.dataset.walk)}});['pointerup','pointercancel'].forEach(t=>document.addEventListener(t,()=>view3d?.setWalk?.(0)));document.addEventListener('fullscreenchange',()=>{if(!document.fullscreenElement&&vrStereo){vrStereo=false;view3d?.setStereo?.(false);const b=document.querySelector('[data-action="vr-stereo"]');if(b){b.setAttribute('aria-pressed','false');b.innerHTML=icon('vr')+' Chế độ kính VR'}}});
window.addEventListener('hashchange',()=>{quizChoice=null;quizFeedback='';hotspot=0;render();scrollTo(0,0)});window.addEventListener('pagehide',()=>{stopCamera();stopAudio()});document.addEventListener('visibilitychange',()=>{if(document.hidden&&stream){stopCamera();render()}});
async function init(){if(!window.CUCHI_STANDALONE&&(location.protocol==='http:'||location.protocol==='https:')){try{const res=await fetch('/api/content',{signal:AbortSignal.timeout(2000)});if(res.ok){const data=await res.json();if(data.app==='cuchi-stories'&&Array.isArray(data.stories)){stories=data.stories;serverMode=true;csrf=data.csrf}}}catch{}}render()}
init();
